<script setup>
import FinancialWorkspace from '../../../Components/Accounting/FinancialWorkspace.vue'
import { computed, reactive, watch } from 'vue'
import { Head, router } from '@inertiajs/vue3'
import AdminLayout from '../../../Layouts/AdminLayout.vue'
import PageHeader from '../../../Components/Ui/PageHeader.vue'
import AccountingNav from '../../../Components/Accounting/AccountingNav.vue'
import AccountingPanel from '../../../Components/Accounting/AccountingPanel.vue'
import { localDateInput } from '../../../Utils/dateInput'
defineOptions({layout:AdminLayout})
const props=defineProps({report:Object,currency:Object,exports:Object,urls:Object});const r=computed(()=>props.report);const form=reactive({from:r.value.period.from,to:r.value.period.to});const money=v=>`${new Intl.NumberFormat('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0))} ${props.currency.symbol}`;const totalCosts=computed(()=>['cogs','waste','expenses','refunds'].reduce((s,k)=>s+Number(r.value.costs[k]||0),0));const visit=()=>router.get(props.urls.index,form,{preserveState:true,preserveScroll:true});function month(offset=0){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+offset);const first=new Date(d.getFullYear(),d.getMonth(),1);const last=offset===0?new Date():new Date(d.getFullYear(),d.getMonth()+1,0);form.from=localDateInput(first);form.to=localDateInput(last);visit()}const rows=computed(()=>[{label:'إجمالي المبيعات',value:r.value.sales.gross_sales,tone:'normal'},{label:'الخصومات',value:-r.value.sales.discounts_total,tone:'deduction'},{label:'صافي المبيعات',value:r.value.sales.net_sales,tone:'subtotal'},{label:'تكلفة المواد المباعة',value:-r.value.costs.cogs,tone:'deduction'},...(Number(r.value.costs.waste)>0?[{label:'الهدر',value:-r.value.costs.waste,tone:'deduction'}]:[]),{label:'الربح الإجمالي',value:r.value.profit.gross_profit,tone:'subtotal'},{label:'المصاريف التشغيلية',value:-r.value.costs.expenses,tone:'deduction'},...(Number(r.value.costs.refunds)>0?[{label:'الاستردادات',value:-r.value.costs.refunds,tone:'deduction'}]:[])])

const resultState = computed(() => Number(r.value.profit.net_profit) < 0 ? 'loss' : Number(r.value.profit.net_profit) > 0 ? 'profit' : 'neutral')
const resultLabel = computed(() => resultState.value === 'loss' ? 'صافي الخسارة' : resultState.value === 'profit' ? 'صافي الربح' : 'صافي النتيجة')
const resultMessage = computed(() => resultState.value === 'loss' ? 'التكاليف تجاوزت صافي المبيعات في هذه الفترة. راجع تكلفة المواد والهدر والمصاريف.' : resultState.value === 'profit' ? 'المطعم حقق نتيجة موجبة بعد تكلفة المواد والمصاريف والاستردادات.' : 'صافي النتيجة صفر في هذه الفترة.')
watch(() => props.report.period, period => { form.from = period.from; form.to = period.to })
</script>
<template>
<Head title="الأرباح والخسائر"/>
<FinancialWorkspace area="المحاسبة" mode="report">
<template #heading>
<PageHeader title="الأرباح والخسائر" icon="bi-graph-up-arrow" subtitle="هل ربح المطعم أم خسر خلال الفترة، وما الذي صنع النتيجة؟"><template #actions><a :href="exports.xlsx" class="btn btn-outline-success"><i class="bi bi-file-earmark-excel"></i> Excel</a><a :href="exports.pdf" target="_blank" class="btn btn-light"><i class="bi bi-printer"></i> PDF</a></template></PageHeader>
</template>
<template #navigation>
<AccountingNav :urls="urls" active="profitLoss"/>
</template>
<template #filters>
<form class="filter" @submit.prevent="visit"><label><span>من</span><input v-model="form.from" type="date" class="form-control"></label><label><span>إلى</span><input v-model="form.to" type="date" class="form-control"></label><button class="btn btn-primary"><i class="bi bi-search"></i> عرض</button><span></span><button type="button" @click="month(0)">هذا الشهر</button><button type="button" @click="month(-1)">الشهر السابق</button></form>
</template>
<template #metrics>
<div class="kpis"><article><span><i class="bi bi-receipt"></i></span><div><small>صافي المبيعات</small><strong>{{money(r.sales.net_sales)}}</strong></div></article><article><span><i class="bi bi-box-seam"></i></span><div><small>تكلفة المواد</small><strong>{{money(r.costs.cogs)}}</strong></div></article><article><span><i class="bi bi-wallet2"></i></span><div><small>إجمالي التكاليف</small><strong>{{money(totalCosts)}}</strong></div></article><article><span><i class="bi bi-percent"></i></span><div><small>هامش الربح الإجمالي</small><strong>{{Number(r.profit.gross_margin_pct||0).toFixed(1)}}%</strong></div></article></div>
</template>
<section class="result" :class="resultState"><span><i class="bi" :class="resultState === 'loss' ? 'bi-graph-down-arrow' : resultState === 'profit' ? 'bi-graph-up-arrow' : 'bi-dash-lg'"></i></span><div><small>{{resultLabel}}</small><strong>{{money(Math.abs(r.profit.net_profit))}}</strong><em>هامش {{Math.abs(Number(r.profit.net_margin_pct||0)).toFixed(1)}}%</em></div><p>{{resultMessage}}</p></section>
<div class="profit-layout"><AccountingPanel title="ملخص الحساب" :description="`${r.period.from} — ${r.period.to} · من دفتر الأستاذ`" icon="bi-list-check"><div class="statement"><div v-for="row in rows" :key="row.label" :class="row.tone"><span>{{row.label}}</span><strong>{{row.value<0?'− ':''}}{{money(Math.abs(row.value))}}</strong></div><footer :class="resultState"><span>{{resultLabel}}</span><strong>{{money(Math.abs(r.profit.net_profit))}}</strong></footer></div></AccountingPanel><aside><AccountingPanel title="مؤشرات تساعد القرار" description="أرقام تشغيلية مرتبطة بنفس الفترة." icon="bi-speedometer2" tone="blue"><dl><div><dt>عدد الفواتير</dt><dd>{{r.sales.invoice_count||0}}</dd></div><div><dt>متوسط الفاتورة</dt><dd>{{money(r.sales.average_ticket)}}</dd></div><div><dt>متوسط التحصيل اليومي</dt><dd>{{money(r.sales.daily_average)}}</dd></div><div><dt>ذمم لم تُحصّل</dt><dd>{{money(r.sales.unpaid_balance)}}</dd></div><div><dt>هدر المخزون</dt><dd :class="{'warn':r.costs.waste>0}">{{money(r.costs.waste)}}</dd></div></dl></AccountingPanel><section class="formula"><strong>كيف حُسب الصافي؟</strong><span>صافي المبيعات</span><i class="bi bi-dash"></i><span>تكلفة المواد والهدر</span><i class="bi bi-dash"></i><span>المصاريف والاسترداد</span></section></aside></div>
</FinancialWorkspace>

</template>
<style scoped>.filter{display:flex;align-items:end;gap:8px;margin-bottom:10px;padding:10px;border:1px solid var(--line, #DFD7CB);border-radius:12px;background:var(--surface, #FFFDFA)}.filter label{display:grid;gap:4px;width:180px}.filter label>span{font-size:.875rem;font-weight:850}.filter>span{flex:1}.filter>button[type=button]{padding:8px 10px;border:1px solid var(--line, #DFD7CB);border-radius:8px;color:var(--muted, #626B6D);background:var(--surface, #FFFDFA);font-size:.875rem;font-weight:800}.result{display:grid;grid-template-columns:auto auto 1fr;align-items:center;gap:11px;margin-bottom:10px;padding:14px 16px;border:1px solid;border-radius:12px}.result.profit{color:var(--ink, #25343A);border-color:var(--line, #DFD7CB);background:var(--surface, #FFFDFA)}.result.loss{color:#ad2929;border-color:#e7b6b6;background:#fff3f3}.result.neutral{color:var(--muted, #626B6D);border-color:var(--line, #DFD7CB);background:var(--surface, #FFFDFA)}.result>span{display:grid;width:43px;height:43px;place-items:center;border-radius:12px;color:#fff;background:var(--brand, #A3422B)}.result.loss>span{background:#ad2929}.result.neutral>span{background:var(--ink, #25343A)}.result>span i{color:#fff}.result>div{display:grid}.result small{font-size:.875rem}.result strong{font-size:1.15rem}.result em{font-size:.875rem;font-style:normal}.result p{justify-self:end;max-width:470px;margin:0;font-size:.875rem;line-height:1.55}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:11px}.kpis article{display:flex;align-items:center;gap:9px;padding:11px;border:1px solid var(--line, #DFD7CB);border-radius:12px;background:var(--surface, #FFFDFA)}.kpis article>span{display:grid;width:35px;height:35px;place-items:center;border-radius:10px;color:var(--ink, #25343A);background:var(--brand-soft, #F3E3D8)}.kpis article>div{display:grid}.kpis small{color:var(--muted, #626B6D);font-size:.875rem}.kpis strong{font-size:.875rem}.profit-layout{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(280px,.65fr);align-items:start;gap:11px}.profit-layout>aside{display:grid;gap:10px}.statement{display:grid}.statement>div,.statement>footer{display:flex;align-items:center;justify-content:space-between;padding:10px 3px;border-bottom:1px solid var(--line, #DFD7CB)}.statement span,.statement strong{font-size:.875rem}.statement .deduction{color:#a73a2d}.statement .subtotal{padding:11px 9px;border-radius:8px;background:var(--surface, #FFFDFA);font-weight:900}.statement footer{margin-top:6px;padding:13px;border:0;border-radius:10px;font-size:.875rem}.statement footer.profit{color:var(--ink, #25343A);background:var(--brand-soft, #F3E3D8)}.statement footer.neutral{color:var(--muted, #626B6D);background:var(--surface, #FFFDFA)}.statement footer.loss{color:#ad2929;background:#fff0f0}dl{display:grid;margin:0}dl div{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--line, #DFD7CB)}dt{color:var(--muted, #626B6D);font-size:.875rem}dd{margin:0;font-size:.875rem;font-weight:850}.warn{color:#ad5d00}.formula{display:flex;flex-wrap:wrap;align-items:center;gap:5px;padding:12px;border:1px solid #e3c98d;border-radius:12px;color:#8c5200;background:#fff8ea}.formula strong{width:100%;font-size:.875rem}.formula span{font-size:.875rem}.formula i{font-size:.875rem}@media(max-width:950px){.kpis{grid-template-columns:1fr 1fr}.profit-layout{grid-template-columns:1fr}.result{grid-template-columns:auto 1fr}.result p{grid-column:2;justify-self:start}}@media(max-width:620px){.filter{display:grid;grid-template-columns:1fr 1fr}.filter label{width:100%}.filter>span{display:none}.filter .btn{grid-column:1/-1}.result p{display:none}.kpis{grid-template-columns:1fr 1fr}}
.result{grid-template-columns:50px minmax(200px,1fr) minmax(220px,.85fr);gap:20px;padding:26px;background:#FFFDFA}.result strong{font-size:36px;line-height:1.5}.result p{font-size:14px;color:#626B6D}.result small{font-size:15px;font-weight:700}.statement>div{padding:16px 10px}.statement strong{font-size:16px}.statement footer{padding:20px;font-size:20px}.statement footer strong{font-size:24px}.formula{background:#F7F3ED;border-color:#DFD7CB;color:#626B6D}@media(max-width:700px){.result{grid-template-columns:42px 1fr;padding:20px}.result strong{font-size:28px}.result p{grid-column:1/-1}}
</style>
